[
  # `do_parse/2` is generated by `Md.Engine`'s macros: hundreds of clauses
  # produced by `Enum.each` over the syntax map. Dialyzer cannot prove that the
  # resulting clause set terminates, so it infers `no_return()` and flags the
  # `@spec` as an invalid contract. The spec is correct -- the parser is
  # exercised by the whole test suite -- so the warning is suppressed here
  # rather than by loosening the spec. This is the *only* suppressed warning:
  # anything else must be fixed, not silenced.
  {"lib/md/parser/engine.ex", :invalid_contract, 1}
]
